{
  "critique": [
    {
      "design": "r2A",
      "good": "The region labels are easy to scan, with only the long Europe, Middle East & Africa label wrapping. Equal month widths keep the figures aligned and intact.",
      "problems": "The reader must scroll to see the later months, which makes comparing all six months across a row less immediate.",
      "cause": "The 125px region column and six 59px month columns produce a 480px table, 120px wider than the viewport."
    },
    {
      "design": "r2B",
      "good": "All words and sales figures remain intact, and more months are visible initially than in the other designs. The equal month widths support comparison.",
      "problems": "Most region names wrap, and the four-line Europe label makes its row much taller than the others. The resulting vertical spread makes the table harder to scan as a whole.",
      "cause": "The 80px region column leaves only 59px for text. The six 59px month columns still make the table 75px wider than the viewport."
    },
    {
      "design": "r2C",
      "good": "Region labels are easy to read, sales figures stay intact, and the month columns have a consistent rhythm.",
      "problems": "The wider region column does not reduce the table height or the longest label's line count compared with r2A, but it pushes more monthly data beyond the viewport.",
      "cause": "The 150px region column adds 25px to r2A without changing its row heights; the table overflows by 145px."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-110",
      "widths": [110, 59, 59, 59, 59, 59, 59],
      "change": "Reduce the region column from r2A to gain 15px of initial monthly visibility while testing whether the labels retain a compact wrapping pattern."
    },
    {
      "name": "compact-100",
      "widths": [100, 59, 59, 59, 59, 59, 59],
      "change": "Try a middle ground between r2A and r2B: give the region labels more room than r2B while reducing horizontal scrolling by 25px from r2A."
    },
    {
      "name": "minimum-label",
      "widths": [78, 59, 59, 59, 59, 59, 59],
      "change": "Test the narrowest region column supported by the stated longest word, leaving 57px for text. This explores the maximum initial visibility possible while keeping words and figures intact."
    }
  ]
}
